70:uri_type str2uri_type(char * buf)
71:{
72:     int scheme = 0;
73:     uri_type type = ERROR_URI_T;
74:     scheme=buf[0]+(buf[1]<<8)+(buf[2]<<16)+(buf[3]<<24);
75:     scheme|=0x20202020;
76:     if (scheme==SIP_SCH){
77:             type=SIP_URI_T;
78:     }else if(scheme==SIPS_SCH){
79:             if(buf[4]==':')
80:                     type=SIPS_URI_T;
81:             else type = ERROR_URI_T;
82:     }else if (scheme==TEL_SCH){
83:             type=TEL_URI_T;
84:     }else if (scheme==URN_SERVICE_SCH){
85:             if (memcmp(buf+3,URN_SERVICE_STR,URN_SERVICE_STR_LEN) == 0) {
86:                     type=URN_SERVICE_URI_T;
87:             }
88:             else if (memcmp(buf+3,URN_NENA_SERVICE_STR,URN_NENA_SERVICE_STR_LEN) == 0) {
89:                     type=URN_NENA_SERVICE_URI_T;
90:             }
